   128→            segmentsRef.current.push({
   129→              type: 'tool',
   130→              toolResult: pending,
   131→            });
   132→            setMessages((prev) =>
   133→              prev.map((m) =>
   134→                m.id === assistantId
   135→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
   136→                  : m
   137→              )
