   187→              prev.map((m) =>
   188→                m.id === assistantId
   189→                  ? { ...m, segments: [...segmentsRef.current] }
   190→                  : m
   191→              )
   192→            );
   193→          },
   194→          onSubagentEnd: (data) => {
   195→            segmentsRef.current.push({
   196→              type: 'subagent_end',
   197→              subagentId: data.id,
   198→              subagentName: data.name,
   199→              chart_spec: data.chart_spec,
   200→              text: data.result,
   201→            });
   202→            setMessages((prev) =>
   203→              prev.map((m) =>
   204→                m.id === assistantId
   205→                  ? { ...m, segments: [...segmentsRef.current] }
