#### 2.2 Question Store - Coordination Layer

**File:** `/home/cyyeh/repos/duckdb-data-agent/backend/app/pending_questions.py`

Thread-safe store coordinating between the SSE stream generator and the `/api/chat/respond` endpoint:

```python
class PendingQuestionStore:
    def __init__(self):
        self._pending: dict[str, dict] = {}  # keyed by session_id

    def create(self, session_id: str, question_data: dict) -> str:
        """Store a pending question and return a unique question_id."""
        question_id = str(uuid.uuid4())
        self._pending[session_id] = {
            "question_id": question_id,
            "data": question_data,
            "event": asyncio.Event(),  # Synchronization primitive
            "answer": None,
        }
        return question_id

    async def wait(self, session_id: str, question_id: str, timeout: float = 300.0):
        """Wait for the user's answer. Returns None on timeout."""
        entry = self._pending.get(session_id)
        try:
            await asyncio.wait_for(entry["event"].wait(), timeout=timeout)
            return entry["answer"]
        except asyncio.TimeoutError:
            return None
        finally:
            del self._pending[session_id]  # Clean up

    def respond(self, session_id: str, question_id: str, answer: dict) -> None:
        """Set the answer and signal the waiter."""
        entry = self._pending.get(session_id)
        entry["answer"] = answer
        entry["event"].set()  # Wake up the waiting task
```

