      (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
    );
    if (segIdx !== -1) {
      segmentsRef.current[segIdx] = {
        ...segmentsRef.current[segIdx],
        userAnswer: answers,
      };
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantIdRef.current
            ? { ...m, segments: [...segmentsRef.current] }
            : m
        )
      );
    }

    // POST to backend
    try {
      await fetch('/api/chat/respond', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
        },
        body: JSON.stringify({
          question_id: questionId,
          answers,
          free_text: freeText || null,
        }),
      });
    } catch (e) {
      console.error('Failed to respond to question:', e);
    }
  },
  [userSessionId]
);
```

---

### 4. DATA FLOW DIAGRAM

```
Agent (Claude) in Sidecar Container
    |
    | Calls ask_user_question(question, options, multi_select)
    |
    v
MCP SSE Handler (/mcp/sse)
    | Stores question in PendingQuestionStore
    | Returns question_id to agent
    |
    v
SSE Stream (backend/app/agent.py)
    | Detects tool call, polls for pending question
    | Emits: event: user_question
    |        data: {question_id, question, options, multi_select}
    |
    v
Frontend (agentService.ts)
    | Parses SSE event
    | Calls onUserQuestion callback
    |
    v
AgentContext
    | Creates 'user_question' segment
    | Updates message with segments
    |
    v
MessageBubble Component
    | Renders thinking/answer/charts above question
    | Displays UserQuestion component
    |
    v
UserQuestion Component (Interactive UI)
    | User clicks option(s) or types free-text
    | handleOptionClick / handleSubmitMulti / handleSubmitFreeText
    |
    v
respondToQuestion Hook
    | Updates segment with userAnswer
    | POST /api/chat/respond with {question_id, answers, free_text}
    |
    v
Backend Chat Route (routes/chat.py)
    | Validates pending question
    | Calls pending_question_store.respond()
    |
    v
PendingQuestionStore
    | Sets answer on event
    | Signals asyncio.Event()
    |
    v
MCP Handler (mcp_sse.py)
    | await pending_question_store.wait() returns answer
    | Returns answer to agent via MCP tool result
    |
    v
Agent Continues Execution
    | Uses user's answer to refine reasoning
    | May call ask_user_question again or proceed
```

---

### 5. KEY FILES REFERENCE

| File | Purpose | Key Components |
|------|---------|-----------------|
| `/backend/app/mcp_sse.py` | MCP tool definitions & execution | `ask_user_question` tool handler |
| `/backend/app/pending_questions.py` | Question/answer coordination | `PendingQuestionStore` class |
| `/backend/app/agent.py` | SSE streaming & agent orchestration | Question detection (line 403), SSE events |
| `/backend/app/routes/chat.py` | HTTP endpoints | `/api/chat/respond` endpoint |
| `/frontend/src/types.ts` | TypeScript interfaces | `UserQuestionData`, `ContentSegment` |
| `/frontend/src/components/UserQuestion.tsx` | Interactive question UI | Option selection, free-text input, submit |
| `/frontend/src/components/MessageBubble.tsx` | Message display | Question segment rendering |
| `/frontend/src/agent/agentService.ts` | SSE event parsing | `user_question` event handler |
| `/frontend/src/contexts/AgentContext.tsx` | React state management | `onUserQuestion` callback, `respondToQuestion` hook |

---

### 6. AGENT SYSTEM PROMPT - CLARIFICATION INSTRUCTIONS

**File:** `/backend/app/agent.py` (lines 20-48)

The agent is instructed to use clarification:

```python
Clarification:
- When the user's request is ambiguous or could be interpreted in multiple ways, 
  use the ask_user_question tool to ask for clarification before proceeding.
- Provide 2-4 clear, concise options for the user to choose from.
- Each option should have a short label and optional description.
- Only ask when genuinely needed — don't over-ask for trivial decisions.
```

---

### 7. TESTING

**File:** `/backend/tests/test_pending_questions.py`

Comprehensive test suite covering:
- Question creation and ID generation
- Question data storage/retrieval
- Answer synchronization with asyncio.Event
- Timeout handling (300s default)
- Session isolation (multiple sessions don't interfere)
- Cleanup on completion

---

### 8. INTERNATIONALIZATION (i18n)

Supported translations for question UI:
- `questionFromAgent` - Label for incoming question
- `questionAnswered` - Label for answered question
- `other` - "Other" button for free-text option
- `hideOther` - Hide free-text option
- `typeYourAnswer` - Placeholder for text input
- `submit` - Submit button label

Supported languages: English (en), Traditional Chinese (zh-TW)

---

## SUMMARY

The "user_ask_question" tool is a **sophisticated async coordination system** that:

1. **Pauses agent execution** when clarification is needed
2. **Sends structured questions** to the UI via SSE with options and multi-select support
3. **Displays interactive UI** with optional free-text input
4. **Coordinates responses** between frontend and backend using asyncio primitives
5. **Resumes agent execution** with the user's answer
6. **Supports timeout handling** (5-minute default) if user doesn't respond

The implementation is elegant and scalable, with clear separation of concerns: MCP tool interface → pending store → SSE streaming → frontend service → React components → context provider → API handler → store signaling.

